# -*- coding: utf-8 -*-

import re
import shlex

from .common._base import BaseCheck


DEFAULT_MDB_PARAMETERS = 'shmmax,seminfo_semmsl,maxfiles,maxuproc,minfree,msginfo_msgmax'
DEFAULT_NDD_PARAMETERS = (
    '/dev/tcp:tcp_conn_req_max_q,'
    '/dev/tcp:tcp_conn_req_max_q0,'
    '/dev/tcp:tcp_keepalive_interval,'
    '/dev/tcp:tcp_time_wait_interval,'
    '/dev/ip:ip_forwarding'
)
ULIMIT_COMMAND = 'ulimit -n'


class Check(BaseCheck):
    USE_HOST_CONNECTION = True
    CONNECTION_METHOD = 'paramiko'
    PARAMIKO_AUTH_TIMEOUT_SEC = 30

    def _credential_value(self, key, default=None):
        value = self.get_application_credential_value(key, default=None)
        if value not in (None, ''):
            return value
        return self.get_connection_value(key, default=default)

    def _is_become_enabled(self):
        value = self._credential_value('become', default=False)
        return str(value).strip().lower() in ('1', 'true', 'y', 'yes', 'on')

    def _build_become_command(self):
        method = str(self._credential_value('become_method', default='su -') or 'su -')
        method = ' '.join(method.strip().lower().split())
        user = str(self._credential_value('become_user', default='root') or 'root').strip() or 'root'

        if method == 'su':
            return 'su ' + shlex.quote(user)
        if method == 'su -':
            return 'su - ' + shlex.quote(user)
        if method == 'sudo':
            return 'sudo -u ' + shlex.quote(user) + ' -i'
        raise ValueError(f'unsupported become_method: {method}')

    def _build_paramiko_commands(self, commands):
        command_items = list(commands)
        if not self._is_become_enabled():
            return command_items

        return [
            {
                'command': self._build_become_command(),
                'timeout': 1,
                'ignore_prompt': True,
            },
            {
                'command': str(self._credential_value('become_password', default='') or ''),
                'hide_command': True,
            },
        ] + command_items

    def _trim_become_command_history(self):
        if not self._is_become_enabled() or not self._command_history:
            return

        try:
            become_command = self._build_become_command()
        except ValueError:
            return

        filtered = []
        skip_next_password = False
        for item in self._command_history:
            command = item.get('cmd', '')
            if command == become_command:
                skip_next_password = True
                continue
            if skip_next_password and command == '*******':
                skip_next_password = False
                continue
            skip_next_password = False
            filtered.append(item)

        self._command_history[:] = filtered

    def _run_check_commands(self, commands):
        try:
            results = self._run_paramiko_commands(self._build_paramiko_commands(commands))
        except ValueError as exc:
            return {}, {'rc': 1, 'stdout': '', 'stderr': str(exc)}

        self._trim_become_command_history()

        result_map = {}
        for result in results:
            command = result.get('command')
            if command in commands:
                result_map[command] = result

        missing_commands = [command for command in commands if command not in result_map]
        if missing_commands:
            failed_result = next((item for item in results if item.get('rc') != 0), None)
            if failed_result:
                return result_map, failed_result
            return result_map, {
                'rc': 1,
                'stdout': '',
                'stderr': 'paramiko command result not found: ' + ', '.join(missing_commands),
            }

        return result_map, None

    def _split_list(self, value):
        return [
            token.strip()
            for token in re.split(r'[|,\n]+', str(value or ''))
            if token.strip()
        ]

    def _normalize_value(self, value):
        normalized = re.sub(r'\s+', ' ', str(value or '').strip())
        if re.match(r'^0t[0-9]+$', normalized):
            return normalized[2:]
        return normalized

    def _has_expected_value(self, value):
        return value is not None and str(value).strip() != ''

    def _build_mdb_command(self, parameters):
        queries = [shlex.quote(name + '/D') for name in parameters]
        queries.append(shlex.quote('$q'))
        return "printf '%s\\n' " + ' '.join(queries) + ' | mdb -k'

    def _parse_mdb_output(self, text, parameters):
        parsed = {}
        skipped_lines = []

        for raw_line in str(text or '').splitlines():
            line = raw_line.strip()
            if not line:
                continue
            if line.startswith('mdb:'):
                skipped_lines.append(raw_line)
                continue

            matched = False
            for name in parameters:
                colon_match = re.match(r'^' + re.escape(name) + r'\s*:\s*(.+)$', line)
                space_match = re.match(r'^' + re.escape(name) + r'\s+(.+)$', line)
                match = colon_match or space_match
                if not match:
                    continue
                value = self._normalize_value(match.group(1))
                if value and '/D' not in value:
                    parsed[name] = value
                    matched = True
                    break

            if not matched:
                skipped_lines.append(raw_line)

        return parsed, skipped_lines

    def _parse_ndd_parameter(self, token):
        text = str(token or '').strip()
        if text.startswith('ndd:'):
            text = text.split(':', 1)[1].strip()

        if ':' in text:
            device, parameter = text.split(':', 1)
            device = device.strip()
            parameter = parameter.strip()
        else:
            parts = text.split()
            if len(parts) >= 2:
                device, parameter = parts[0].strip(), parts[1].strip()
            else:
                parameter = text
                device = '/dev/ip' if parameter.startswith('ip_') else '/dev/tcp'

        if not device.startswith('/'):
            device = '/dev/' + device.strip('/')

        return {
            'device': device,
            'parameter': parameter,
            'key': f'ndd:{device}:{parameter}',
        }

    def _get_ndd_parameters(self):
        raw = self.get_threshold_var(
            'required_ndd_parameters',
            default=DEFAULT_NDD_PARAMETERS,
            value_type='str',
        )
        items = []
        seen = set()
        for token in self._split_list(raw):
            item = self._parse_ndd_parameter(token)
            if not item['parameter'] or item['key'] in seen:
                continue
            items.append(item)
            seen.add(item['key'])
        return items

    def _ndd_command(self, item):
        return 'ndd -get {device} {parameter}'.format(
            device=shlex.quote(item['device']),
            parameter=shlex.quote(item['parameter']),
        )

    def _detect_result_error(self, result):
        return self._detect_command_error(
            result.get('stdout', ''),
            result.get('stderr', ''),
            extra_patterns=[
                'permission denied',
                'not supported',
                'unknown userland error',
                'unknown symbol',
                'invalid argument',
                'no such file',
                'not found',
            ],
        )

    def _expected_for_key(self, threshold_map, key, fallback_key=None):
        if key in threshold_map:
            return threshold_map.get(key)
        if fallback_key and fallback_key in threshold_map:
            return threshold_map.get(fallback_key)
        return None

    def _evaluate_value(self, key, actual_value, expected_value):
        actual = self._normalize_value(actual_value)
        expected = self._normalize_value(expected_value)
        item = {
            'key': key,
            'actual_value': actual,
            'expected_value': expected if self._has_expected_value(expected_value) else '',
            'comparison': 'equals' if self._has_expected_value(expected_value) else 'exists',
        }

        if not actual:
            item['status'] = 'empty'
            return item

        if self._has_expected_value(expected_value) and actual != expected:
            item['status'] = 'mismatch'
            return item

        item['status'] = 'matched'
        return item

    def _build_thresholds(self, required_parameters, ndd_items, threshold_map, failure_keywords):
        thresholds = {
            'required_parameters': required_parameters,
            'required_ndd_parameters': [item['key'] for item in ndd_items],
            'failure_keywords': failure_keywords,
        }

        for name in required_parameters:
            expected = threshold_map.get(name)
            if self._has_expected_value(expected):
                thresholds[name] = self._normalize_value(expected)

        for item in ndd_items:
            expected = self._expected_for_key(threshold_map, item['key'], item['parameter'])
            if self._has_expected_value(expected):
                thresholds[item['key']] = self._normalize_value(expected)

        ulimit_expected = threshold_map.get('ulimit_n')
        if self._has_expected_value(ulimit_expected):
            thresholds['ulimit_n'] = self._normalize_value(ulimit_expected)

        return thresholds

    def _build_metrics(self, mdb_values, ndd_values, ulimit_value, matched, missing, empty, mismatched, skipped):
        return {
            'mdb': {
                'checked_count': len(mdb_values),
                'parameters': mdb_values,
                'skipped_lines': skipped,
            },
            'ndd': {
                'checked_count': len(ndd_values),
                'parameters': ndd_values,
            },
            'ulimit_n': ulimit_value,
            'matched_items': matched,
            'missing_items': missing,
            'empty_items': empty,
            'mismatched_items': mismatched,
        }

    def run(self):
        threshold_map = self.get_threshold_list_map()
        required_parameters = self._split_list(
            self.get_threshold_var(
                'required_parameters',
                default=DEFAULT_MDB_PARAMETERS,
                value_type='str',
            )
        )
        failure_keywords = self._split_list(
            self.get_threshold_var('failure_keywords', default='', value_type='str')
        )
        ndd_items = self._get_ndd_parameters()

        if not required_parameters:
            return self.fail(
                '점검 기준 없음',
                message='mdb -k로 조회할 required_parameters가 비어 있습니다.',
            )
        if not ndd_items:
            return self.fail(
                '점검 기준 없음',
                message='ndd -get으로 조회할 required_ndd_parameters가 비어 있습니다.',
            )

        mdb_command = self._build_mdb_command(required_parameters)
        ndd_commands = {
            item['key']: self._ndd_command(item)
            for item in ndd_items
        }
        commands = [mdb_command] + list(ndd_commands.values()) + [ULIMIT_COMMAND]
        command_results, setup_error = self._run_check_commands(commands)

        if setup_error:
            rc = setup_error.get('rc')
            err = setup_error.get('stderr', '')
            out = setup_error.get('stdout', '')
            if self._is_connection_error(rc, err):
                return self.fail(
                    '호스트 연결 실패',
                    message=(err or 'Paramiko SSH 연결 확인에 실패했습니다.').strip(),
                    stderr=(err or '').strip(),
                )
            return self.fail(
                '점검 명령 실행 실패',
                message='Solaris 커널 파라미터 점검 명령을 정상적으로 완료하지 못했습니다.',
                stdout=(out or '').strip(),
                stderr=(err or '').strip(),
            )

        for command in commands:
            result = command_results[command]
            rc = result.get('rc')
            out = (result.get('stdout') or '').strip()
            err = (result.get('stderr') or '').strip()

            if self._is_connection_error(rc, err):
                return self.fail(
                    '호스트 연결 실패',
                    message=(err or 'Paramiko SSH 연결 확인에 실패했습니다.').strip(),
                    stderr=err,
                )
            if rc != 0:
                return self.fail(
                    '점검 명령 실행 실패',
                    message=f'{command} 명령 실행에 실패했습니다.',
                    stdout=out,
                    stderr=err,
                )

            command_error = self._detect_result_error(result)
            if command_error:
                return self.fail(
                    '점검 명령 실행 실패',
                    message=f'{command} 출력에서 실행 오류가 확인되었습니다: {command_error}',
                    stdout=out,
                    stderr=err,
                )

        combined_output = '\n'.join(
            (command_results[command].get('stdout') or '').strip()
            for command in commands
            if (command_results[command].get('stdout') or '').strip()
        )
        matched_failure_keywords = [
            keyword for keyword in failure_keywords
            if keyword.lower() in combined_output.lower()
        ]
        if matched_failure_keywords:
            return self.fail(
                '커널 파라미터 실패 키워드 감지',
                message='출력에서 실패 키워드가 확인되었습니다: ' + ', '.join(matched_failure_keywords),
                stdout=combined_output,
            )

        mdb_values, skipped_lines = self._parse_mdb_output(
            command_results[mdb_command].get('stdout', ''),
            required_parameters,
        )

        missing_items = []
        empty_items = []
        mismatched_items = []
        matched_items = []

        for name in required_parameters:
            if name not in mdb_values:
                missing_items.append({'key': name, 'source': 'mdb'})
                continue

            evaluated = self._evaluate_value(name, mdb_values[name], threshold_map.get(name))
            evaluated['source'] = 'mdb'
            if evaluated['status'] == 'matched':
                matched_items.append(evaluated)
            elif evaluated['status'] == 'empty':
                empty_items.append(evaluated)
            else:
                mismatched_items.append(evaluated)

        ndd_values = {}
        for item in ndd_items:
            command = ndd_commands[item['key']]
            value = self._normalize_value(command_results[command].get('stdout', ''))
            ndd_values[item['key']] = {
                'device': item['device'],
                'parameter': item['parameter'],
                'value': value,
            }
            expected = self._expected_for_key(threshold_map, item['key'], item['parameter'])
            evaluated = self._evaluate_value(item['key'], value, expected)
            evaluated['source'] = 'ndd'
            evaluated['device'] = item['device']
            evaluated['parameter'] = item['parameter']
            if evaluated['status'] == 'matched':
                matched_items.append(evaluated)
            elif evaluated['status'] == 'empty':
                empty_items.append(evaluated)
            else:
                mismatched_items.append(evaluated)

        ulimit_value = self._normalize_value(command_results[ULIMIT_COMMAND].get('stdout', ''))
        ulimit_evaluated = self._evaluate_value('ulimit_n', ulimit_value, threshold_map.get('ulimit_n'))
        ulimit_evaluated['source'] = 'ulimit'
        if ulimit_evaluated['status'] == 'matched':
            matched_items.append(ulimit_evaluated)
        elif ulimit_evaluated['status'] == 'empty':
            empty_items.append(ulimit_evaluated)
        else:
            mismatched_items.append(ulimit_evaluated)

        thresholds = self._build_thresholds(
            required_parameters,
            ndd_items,
            threshold_map,
            failure_keywords,
        )
        metrics = self._build_metrics(
            mdb_values,
            ndd_values,
            ulimit_value,
            matched_items,
            missing_items,
            empty_items,
            mismatched_items,
            skipped_lines,
        )

        if missing_items or empty_items or mismatched_items:
            details = []
            if missing_items:
                details.append('누락: ' + ', '.join(item['key'] for item in missing_items))
            if empty_items:
                details.append('빈 값: ' + ', '.join(item['key'] for item in empty_items))
            if mismatched_items:
                details.append(
                    '값 불일치: ' + ', '.join(
                        f"{item['key']}(expected={item['expected_value']}, actual={item['actual_value']})"
                        for item in mismatched_items
                    )
                )
            return self.fail(
                '커널 파라미터 기준 불일치',
                message='Solaris 커널 파라미터 점검에 실패했습니다. ' + '; '.join(details),
                stdout=combined_output,
                metrics=metrics,
                thresholds=thresholds,
                reasons='mdb -k, ndd -get, ulimit -n 조회값이 기준과 일치하지 않습니다.',
            )

        matched_summary = ', '.join(
            f"{item['key']}={item['actual_value']}"
            for item in matched_items
        )
        return self.ok(
            metrics=metrics,
            thresholds=thresholds,
            reasons='mdb -k, ndd -get, ulimit -n 기준 항목이 모두 조회되었고 기대값이 있는 항목은 일치합니다.',
            message='Solaris 커널 파라미터 점검이 정상 수행되었습니다. 일치 항목: ' + matched_summary,
        )


CHECK_CLASS = Check
